<?php
/**
 * Plugin adapter for Yay Bulk Order Pro.
 * Generated by yaycommerce-init. Edit values as needed.
 *
 * @package yaycommerce/yay-bulk-order
 */

namespace YayBulkOrder\Pro;

defined( 'ABSPATH' ) || exit;

/**
 * YayBulkOrder Adapter (Pro)
 */
class YayBulkOrderProLicenseAdapter implements \YayBulkOrderScoped\YayCommerce\AdminShell\License\Contracts\LicenseConfigAdapter {
    // --- Menu methods ---
    public function get_menu_title(): string {
        return 'Yay Bulk Order'; }
    public function get_page_title(): string {
        return 'Yay Bulk Order'; }
    public function get_menu_slug(): string {
        return 'yay_bulk_order'; }
    public function get_settings_page_callback(): ?callable {
        return function () {
            echo '<div id="yay-bulk-order-app-admin"></div>';
        };
    } // Set your render callback here
    public function get_settings_page_position(): ?int {
        return YAYBULKORDER_MENU_ORDER; }
    public function get_capability(): string {
        return 'manage_woocommerce'; }
    public function get_plugin_basename(): string {
        return YAYBULKORDER_PLUGIN_BASENAME; }
    public function get_settings_label(): string {
        return 'Settings'; }
    public function get_docs_url(): string {
        return 'https://docs.yaycommerce.com/yaybulkorder/'; }
    public function get_pro_url(): string {
        return ''; }

    // --- License methods ---
    public function get_plugin_slug(): string {
        return 'yay-bulk-order-pro'; }
    public function get_plugin_name(): string {
        return 'Yay Bulk Order Pro'; }
    public function get_plugin_version(): string {
        return defined( 'YAYBULKORDER_VERSION' ) ? YAYBULKORDER_VERSION : '0.0.0'; }
    public function get_plugin_file(): string {
        return YAYBULKORDER_FILE; }
    public function get_item_id(): int {
        return 1; } // TODO: EDD setup
    public function get_store_url(): string {
        return 'https://yaycommerce.com/'; }
    public function get_store_link(): string {
        return 'https://yaycommerce.com/yay-bulk-order-for-woocommerce/'; }

    /**
     * Check if this plugin has an active, non-expired license.
     */
    public static function is_licensed(): bool {
        $info = get_option( 'yay-bulk-order-pro_license_info', [] );
        $key  = get_option( 'yay-bulk-order-pro_license_key', '' );
        return ! empty( $key ) && ! empty( $info ) && 'expired' !== ( $info['license'] ?? '' );
    }
}
